landing=()=>{A().innerHTML=`<section class="landing official"><nav class="nav"><div class="brand"><i>✦</i> آفاق</div><button onclick="auth('login')">تسجيل الدخول</button></nav><main class="official-hero"><img src="/assets/ministry-logo.png" class="moe-logo" alt="شعار وزارة التربية والتعليم"><div class="school-official-name">مدرسة بعيا للتعليم الأساسي والثانوي</div><h1>نصنع التميّز<br><em>ونفتح آفاق الإنجاز</em></h1><p>منصة مدرسية رسمية للميثاق والقيم الإيجابية والشراكة مع الأسرة والاحتفاء بالإنجاز.</p><button class="primary" onclick="auth('signup')">إنشاء حساب</button></main><div class="public-nav">${['على خطى زايد','القيم الإيجابية','سفيرات الميثاق','الفصل الإيجابي','شراكة الأسرة','قصص النجاح'].map(x=>`<button onclick="publicPage('${x}')">${x}</button>`).join('')}</div></section>`};

const afaqDashboardWithStats=dashboard;
dashboard=(page='الرئيسية')=>{afaqDashboardWithStats(page);const portal=document.querySelector('.dashboard');portal?.classList.add('afaq-portal',`role-${role}`);if(role!=='student')return;portal?.classList.add('student-portal');const viewBox=document.querySelector('#view');if(page==='الرئيسية'&&viewBox)viewBox.insertAdjacentHTML('afterbegin',`<section class="student-welcome"><div class="seal">✦</div><div><b>بوابة الطالب</b><small>مدرسة بعيا للتعليم الأساسي والثانوي · مسارك نحو التميّز</small></div></section>`) };

submitValue=async(e,kind)=>{e.preventDefault();const f=new FormData(e.target);try{await api('submissions',{student:user.name,grade:user.grade,section:user.section,owner_email:user.email,kind,text:f.get('text'),file:await asFile(e.target.proof)});const value=kind.split(': ').slice(1).join(': ');await api('certificates',{owner_email:user.email,owner_name:user.name,title:'شهادة شكر وتقدير',detail:`تقديرًا لمشاركتك في قيمة [${value}].`});alert('تم حفظ الدليل وإصدار شهادة الشكر.');dashboard('شهاداتي')}catch(err){alert(err.message)}};

async function loadCertificates(){try{const list=await api('certificates?email='+encodeURIComponent(user.email));window.afaqCertificates=list;const box=document.querySelector('#view');if(!box)return;box.innerHTML=`<section class="card"><div class="certificate-card-head"><img src="/assets/ministry-logo.png" class="certificate-list-logo" alt="شعار الوزارة"><div><h3>شهاداتي</h3><small>سجل شهادات الطالب الرسمية</small></div></div>${list.length?list.map((c,i)=>`<div class="item"><span class="bubble">✦</span><div><b>${c.title}</b><small>${c.detail}</small></div><button class="outline" onclick="downloadCertificate(${i})">تنزيل الشهادة</button></div>`).join(''):'<p class="empty">لم تحصلي على شهادات بعد.</p>'}</section>`}catch(err){document.querySelector('#view').innerHTML=`<section class="card"><p class="empty">${err.message}</p></section>`}}

downloadCertificate=async(i)=>{const c=window.afaqCertificates?.[i];if(!c)return;const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1000;const x=canvas.getContext('2d');x.fillStyle='#fcfbf6';x.fillRect(0,0,1600,1000);x.fillStyle='#102b46';x.fillRect(0,0,1600,95);x.strokeStyle='#caa04b';x.lineWidth=14;x.strokeRect(45,45,1510,910);const logo=new Image();logo.src='/assets/ministry-logo.png';await new Promise(resolve=>{logo.onload=resolve;logo.onerror=resolve});if(logo.complete&&logo.naturalWidth)x.drawImage(logo,665,102,270,150);x.fillStyle='#102b46';x.textAlign='center';x.font='bold 57px Arial';x.fillText('شهادة شكر وتقدير',800,335);x.fillStyle='#caa04b';x.fillRect(615,365,370,4);x.fillStyle='#132c45';x.font='31px Arial';x.fillText('تتقدم مدرسة بعيا للتعليم الأساسي والثانوي بالشكر والتقدير إلى',800,450);x.font='bold 58px Arial';x.fillText(c.owner_name,800,545);x.font='32px Arial';x.fillText(c.detail,800,640);x.textAlign='right';x.font='bold 28px Arial';x.fillText('مديرة المدرسة',1390,805);x.font='32px Arial';x.fillText('يلوى المنصوري',1390,850);x.textAlign='left';x.font='27px Arial';x.fillText('مدرسة بعيا للتعليم الأساسي والثانوي',205,850);const a=document.createElement('a');a.download=`شهادة-${c.owner_name}-${c.id}.png`;a.href=canvas.toDataURL('image/png');a.click()};

