downloadCertificate=async(i)=>{const c=window.afaqCertificates?.[i];if(!c)return;const cv=document.createElement('canvas');cv.width=1080;cv.height=1500;const x=cv.getContext('2d');x.fillStyle='#fffefa';x.fillRect(0,0,1080,1500);x.fillStyle='#062d4b';x.beginPath();x.moveTo(0,0);x.lineTo(1080,0);x.lineTo(1080,170);x.lineTo(710,300);x.lineTo(370,300);x.lineTo(0,170);x.fill();x.fillStyle='#caa04b';x.fillRect(0,160,1080,10);x.beginPath();x.moveTo(0,1500);x.lineTo(1080,1500);x.lineTo(1080,1370);x.lineTo(710,1500);x.fill();x.fillStyle='#caa04b';x.fillRect(0,1360,1080,9);const l=new Image();l.src='/assets/ministry-logo-clean.png';await new Promise(r=>{l.onload=r;l.onerror=r});if(l.naturalWidth)x.drawImage(l,390,62,300,105);x.textAlign='center';x.fillStyle='#102b46';x.font='bold 39px Arial';x.fillText('مدرسة بعيا للتعليم الأساسي والثانوي',540,385);x.fillStyle='#caa04b';x.fillRect(270,420,540,4);x.fillStyle='#111';x.font='bold 75px Arial';x.fillText('شهادة شكر وتقدير',540,555);x.fillStyle='#102b46';x.font='32px Arial';x.fillText('تتقدم المدرسة بالشكر والتقدير إلى',540,680);x.fillStyle='#caa04b';x.font='bold 56px Arial';x.fillText('['+c.owner_name+']',540,795);x.fillStyle='#102b46';x.font='34px Arial';x.fillText(c.detail,540,900);x.font='bold 28px Arial';x.fillText('مديرة المدرسة',540,1110);x.font='bold 56px cursive';x.fillText('يلوى المنصوري',540,1195);const a=document.createElement('a');a.download=`شهادة-${c.owner_name}-${c.id}.png`;a.href=cv.toDataURL('image/png');a.click()};
