/* شهادات الاعتماد للمعلمة وولي الأمر */
submitBehavior=async(e)=>{e.preventDefault();const f=new FormData(e.target);const cl=f.get('class').trim();try{await api('submissions',{student:f.get('student'),grade:cl[0]||'',section:cl.slice(-1)||'',kind:'سلوك إيجابي',text:f.get('text'),owner_email:user.email,owner_name:user.name});alert('تم إرسال الترشيح إلى نائب المديرة. عند اعتماده ستصل شهادة شكر إلى شهاداتك.');dashboard()}catch(err){alert(err.message)}};
submitStory=async(e,kind)=>{e.preventDefault();const f=new FormData(e.target);const cl=f.get('class').trim();try{await api('stories',{student:f.get('student'),grade:cl[0]||'',section:cl.slice(-1)||'',author:user.name,author_email:user.email,source_role:kind,text:f.get('text'),file:await asFile(e.target.proof)});alert('تم حفظ القصة وإرسالها إلى نائب المديرة. عند اعتمادها ستصل شهادة شكر إلى شهاداتك.');dashboard(kind==='parent'?'طلباتي السابقة':'الرئيسية')}catch(err){alert(err.message)}};
downloadCertificate=async(i)=>{const c=window.afaqCertificates?.[i];if(!c)return;const cv=document.createElement('canvas');cv.width=1080;cv.height=1600;const x=cv.getContext('2d');const t=new Image();t.src='/assets/certificate-final-template.png';await new Promise(r=>{t.onload=r;t.onerror=r});if(t.naturalWidth)x.drawImage(t,0,0,1080,1600);else{x.fillStyle='#fff';x.fillRect(0,0,1080,1600)};const detail=String(c.detail||'');const charter=/الميثاق|التعه/.test(`${c.title} ${detail}`);const phrase=detail==='خالص الامتنان لجهودك المباركة'||detail.startsWith('تقديراً لمشاركتكم')?detail:(charter?'تقديراً لتعهدك بالالتزام بميثاق المدرسة':'تقديراً لمشاركتك في تعزيز القيم');x.fillStyle='#fff';x.fillRect(60,980,960,305);x.textAlign='center';x.fillStyle='#b37b12';x.font='bold 104px Arial';x.fillText(c.owner_name,540,1125);x.fillStyle='#102b46';x.font='bold 46px Arial';x.fillText(phrase,540,1240);const a=document.createElement('a');a.download=`شهادة-${c.owner_name}-${c.id}.png`;a.href=cv.toDataURL('image/png');a.click()};
